import hashlib,json
from pathlib import Path
from datetime import datetime,timezone
root=Path(__file__).resolve().parents[1];run=root/'run'
def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def command_result(label):
 row=next(x for x in commands if x['label']==label)
 for stream in ['stdout','stderr']:
  assert sha(Path(row[stream+'_path']))==row[stream+'_sha256']
 return row
commands=[json.loads(line) for line in (run/'final-tool-command-evidence.ndjson').read_text().splitlines()]
assert len(commands)==len({x['label'] for x in commands})
expected_rc={'final-tool-build':0,'final-tool-malformed-draft':1,'final-tool-query-all':0,'final-tool-candidate-current':0,'final-tool-profile-reverse':0,'final-tool-damaged-current':1,'final-tool-wrong-root':1,'final-tool-independent-source-check':0,'final-tool-preservation-check':1,'final-tool-preservation-check-corrected':0}
assert {x['label'] for x in commands}==set(expected_rc)
for label,rc in expected_rc.items():assert command_result(label)['returncode']==rc,(label,'unexpected status')
cli=root/'tool-final/tools/photo_data_maintenance/cli.py'
for label in ['final-tool-build','final-tool-malformed-draft','final-tool-candidate-current','final-tool-profile-reverse','final-tool-damaged-current','final-tool-wrong-root']:
 assert command_result(label)['argv'][1]==str(cli)
