assert manifest['validation_status']=='generation_validated';assert manifest['findings_count']['error']==0
independent=read(run/'final-tool-independent-source-link-check.json');preserved=read(run/'final-tool-preservation-check.json');assert independent['status']==preserved['status']=='PASS'
malformed=run/'final-tool-scratch/malformed-draft-report';malformed_manifest=read(malformed/'manifest.json');diagnostics=read(malformed/'findings.json')['findings'];diagnostic=next(x for x in diagnostics if x['rule']=='authored_contract_invalid' and x['message']=="'list' object has no attribute 'setdefault'")
assert malformed_manifest['validation_status']=='invalid';assert malformed_manifest['binding']['generation_id'] is None
assert not Path(command_result('final-tool-malformed-draft')['stderr_path']).read_bytes()
current=read(run/'final-tool-command-logs/final-tool-candidate-current.stdout');reverse=read(run/'final-tool-command-logs/final-tool-profile-reverse.stdout');assert current['paths']==reverse['paths'];assert current['freshness']=='current_verified'
