result={'schema':'independent-final-management-tool-verification/v1','case':5,'round':2,'completed_at_utc':datetime.now(timezone.utc).isoformat(),'scope':'Same frozen cone macro request, same inputs/core/English baseline and same immutable generation; management defense update only','request_origin':qa['request_origin'],'source_root':str(root/'skill'),'runtime_store':str(root/'runtime'),'new_cli_absolute_path':str(cli),'python':commands[0]['argv'][0],'generation_id':qa['generation_id'],'source_fingerprint':qa['source_fingerprint'],'original_report':str(run/'maintenance-report'),'final_report':str(run/'management-final-report'),'code_hashes':codes,'judgments':judgments,'report_member_comparison':preserved['report_member_comparison'],'projection_comparison':{'public_query_evidence_bytes_equal':True,'independent_edge_and_query_projection_equal':True,'independent_source_check_whole_file_bytes_equal':False,'source_proof_rows_equal_after_order_normalization':True,'explanation':'Only order of source_checks/source_files/candidate_source_checks differs due to local unordered touched-node set iteration; source identities, hashes, refs, checks, edge paths and query projections are equal.'},'QA_helper_corrections':[read(run/'final-tool-helper-correction.json')],'incidental_setup_diagnostic':{'issue':'Optional read assumed run/ISOLATION.json after scratch copies had been created','correction':'Read actual round-2/ISOLATION.json; scratch files retained and not mutated again','impact_on_product_evidence':'none'},'final_prompt_en':qa['final_prompt_en'],'final_prompt_sha256':qa['final_prompt_sha256'],'prior_QA_judgments_preserved':True,'new_retrieval_performed':False,'api_image_network_calls':False,'pixel_verification':'NOT_VERIFIED','user_acceptance':'NOT_VERIFIED','cello_behavior_validation_in_this_case':'NOT_VERIFIED; no cello request or activation behavior exercised in this cone case','command_evidence':commands,'artifacts':[{'path':str(p),'sha256':sha(p)} for p in artifacts],'proof_boundary':'Technical report/source/path/freshness evidence only. Complete DATA receiver compatibility, whole meaning fulfillment, mandatory profile activation, image pixels and user acceptance are not inferred from an advisory bundle graph.'}
target=run/'FINAL-TOOL-VERIFICATION.json';assert not target.exists();target.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'file':str(target),'sha256':sha(target),'judgments':{k:v['status'] for k,v in judgments.items()},'commands':len(commands),'prior_seals':[(x['manifest'],x['checked_count']) for x in preserved['frozen_evidence']],'generation_id':result['generation_id']},ensure_ascii=False,indent=2))
